const getPreviewCertificateReadinessV1 = `-- name: GetPreviewCertificateReadinessV1 :one
SELECT EXISTS (
  SELECT 1
  FROM preview_domains AS d
  JOIN preview_leases AS lease
    ON lease.id = d.preview_id AND lease.account_id = d.account_id
  JOIN tunnel_certificate_records AS cert
    ON cert.domain_id = d.id
   AND cert.account_id = d.account_id
   AND cert.target_kind = 'preview_lease'
   AND cert.preview_id = d.preview_id
   AND cert.preview_generation = d.preview_generation
   AND cert.certificate_reference = d.certificate_reference
  WHERE d.id = $1
    AND d.account_id = $2
    AND d.preview_id = $3
    AND d.preview_generation = $4
    AND d.generation = $5
    AND d.hostname = $6
    AND d.ownership_state = 'verified'
    AND d.conflict_state = 'clear'
    AND d.certificate_state = 'ready'
    AND d.certificate_reference IS NOT NULL
    AND lease.generation = d.preview_generation
    AND lease.terminal_state = 'active'
    AND lease.lease_deadline > $7
    AND (lease.user_deadline IS NULL OR lease.user_deadline > $7)
    AND cert.certificate_generation = $8
    AND cert.state = 'active'
    AND cert.expires_at > $7
    AND EXISTS (
      SELECT 1
      FROM tunnel_certificate_edge_distributions AS edge_cert
      WHERE edge_cert.certificate_id = cert.id
        AND edge_cert.edge_node_id = $9
        AND edge_cert.edge_process_epoch = $10
        AND edge_cert.edge_assignment_generation = $11
        AND edge_cert.observed_certificate_generation = cert.certificate_generation
        AND edge_cert.state = 'active'
        AND edge_cert.updated_at >= cert.updated_at
    )
)
`

type GetPreviewCertificateReadinessV1Params struct {
	DomainID                 string
	AccountID                string
	PreviewID                string
	PreviewGeneration        int64
	DomainGeneration         int64
	Hostname                 string
	Now                      time.Time
	CertificateGeneration    int64
	EdgeNodeID               string
	EdgeProcessEpoch         string
	EdgeAssignmentGeneration int64
}

func (q *Queries) GetPreviewCertificateReadinessV1(ctx context.Context, arg GetPreviewCertificateReadinessV1Params) (bool, error) {
	row := q.db.QueryRow(ctx, getPreviewCertificateReadinessV1,
		arg.DomainID,
		arg.AccountID,
		arg.PreviewID,
		arg.PreviewGeneration,
		arg.DomainGeneration,
		arg.Hostname,
		arg.Now,
		arg.CertificateGeneration,
		arg.EdgeNodeID,
		arg.EdgeProcessEpoch,
		arg.EdgeAssignmentGeneration,
	)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

