const upsertTunnelPlatformCertificateTargetV1 = `-- name: UpsertTunnelPlatformCertificateTargetV1 :one
INSERT INTO tunnel_platform_certificate_targets (
  id, kind, hostname, account_id, challenge_reference, generation,
  desired_state, certificate_state, created_at, updated_at
) VALUES (
  $1, $2, $3, $4,
  $5, $6, 'active', 'pending',
  $7, $7
)
ON CONFLICT (id) DO UPDATE
SET id = tunnel_platform_certificate_targets.id
WHERE tunnel_platform_certificate_targets.kind = EXCLUDED.kind
  AND tunnel_platform_certificate_targets.hostname = EXCLUDED.hostname
  AND tunnel_platform_certificate_targets.account_id = EXCLUDED.account_id
  AND tunnel_platform_certificate_targets.challenge_reference = EXCLUDED.challenge_reference
  AND tunnel_platform_certificate_targets.generation = EXCLUDED.generation
RETURNING id, kind, hostname, account_id, challenge_reference, generation, desired_state, certificate_state, certificate_reference, certificate_expires_at, certificate_renewal_attempted_at, certificate_failure_code, retry_count, next_retry_at, created_at, updated_at
`

type UpsertTunnelPlatformCertificateTargetV1Params struct {
	ID                 string
	Kind               string
	Hostname           string
	AccountID          string
	ChallengeReference string
	Generation         int64
	Now                time.Time
}

// Platform wildcard targets are server-owned rows, so they intentionally do
// not use the tunnel_domains/preview_domains existence predicates above. They
// still use the same encrypted certificate and edge-distribution ledger.
// Identity reconciliation is intentionally a lifecycle no-op. Advancing
// updated_at here while retaining a previously scheduled next_retry_at can
// violate next_retry_at > updated_at and also makes an immutable seed look
// like a certificate-state transition.
func (q *Queries) UpsertTunnelPlatformCertificateTargetV1(ctx context.Context, arg UpsertTunnelPlatformCertificateTargetV1Params) (TunnelPlatformCertificateTarget, error) {
	row := q.db.QueryRow(ctx, upsertTunnelPlatformCertificateTargetV1,
		arg.ID,
		arg.Kind,
		arg.Hostname,
		arg.AccountID,
		arg.ChallengeReference,
		arg.Generation,
		arg.Now,
	)
	var i TunnelPlatformCertificateTarget
	err := row.Scan(
		&i.ID,
		&i.Kind,
		&i.Hostname,
		&i.AccountID,
		&i.ChallengeReference,
		&i.Generation,
		&i.DesiredState,
		&i.CertificateState,
		&i.CertificateReference,
		&i.CertificateExpiresAt,
		&i.CertificateRenewalAttemptedAt,
		&i.CertificateFailureCode,
		&i.RetryCount,
		&i.NextRetryAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
